import { test, expect, type APIRequestContext } from '@playwright/test';

const TINY_PNG = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64'
);

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(
  request: APIRequestContext,
  email: string,
  nickname: string
): Promise<{ id: string; email: string; nickname: string }> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status(), 'send-code 应返回 200').toBe(200);
  const sendJson = await sendRes.json();
  expect(sendJson.devCode).toMatch(/^\d{6}$/);

  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode, nickname },
  });
  expect(verifyRes.status(), 'verify-code 应返回 200').toBe(200);
  const verifyJson = await verifyRes.json();
  expect(verifyJson.ok).toBe(true);
  return verifyJson.user;
}

test.describe.serial('发布界面精简化与增强交互体验 E2E 验收套件', () => {
  test('AC-1: 确认内联与弹窗发布编辑器均已移除图片上传与外链按钮', async ({ page }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    await loginUser(page.request, makeEmail('simplify-ui'), '极简体验官');
    await page.goto('/');

    // 1) 检查首页内联发布器
    const inlineForm = page.locator('main form[data-testid="post-composer-form"]').first();
    await expect(inlineForm).toBeVisible({ timeout: 10000 });
    await expect(inlineForm.locator('input[type="file"]')).toHaveCount(0);
    await expect(inlineForm.locator('input[type="url"]')).toHaveCount(0);
    await expect(inlineForm.getByRole('button', { name: /^(图片|更换图片|外链)$/ })).toHaveCount(0);
    await expect(inlineForm.locator('label', { hasText: /^图片$/ })).toHaveCount(0);

    // 2) 打开左侧发布弹窗检查弹窗内发布器
    const leftAside = page.locator('aside').first();
    await leftAside.getByRole('button', { name: /发布动态/ }).first().click();

    const dialog = page.getByRole('dialog').first();
    await expect(dialog).toBeVisible({ timeout: 10000 });
    await expect(dialog.locator('input[type="file"]')).toHaveCount(0);
    await expect(dialog.locator('input[type="url"]')).toHaveCount(0);
    await expect(dialog.getByRole('button', { name: /^(图片|更换图片|外链)$/ })).toHaveCount(0);
    await expect(dialog.locator('label', { hasText: /^图片$/ })).toHaveCount(0);
    await expect(dialog.locator('textarea').first()).toBeVisible();

    expect(pageErrors, '精简发布器渲染不应产生未捕获前端错误').toEqual([]);
  });

  test('AC-2: 拖拽本地图片自动预览上传，并拦截非图片非法文件', async ({ page }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    await loginUser(page.request, makeEmail('drag-upload'), '拖拽测试员');
    await page.goto('/');

    const inlineForm = page.locator('main form[data-testid="post-composer-form"]').first();
    const textarea = inlineForm.locator('textarea').first();
    await expect(textarea).toBeVisible({ timeout: 10000 });

    // 1) 拖入非图片文件（.txt / text/plain）必须被拒绝并显示错误提示
    await textarea.evaluate((el) => {
      const file = new File(['hello malicious file'], 'notes.txt', { type: 'text/plain' });
      const dt = new DataTransfer();
      dt.items.add(file);
      el.dispatchEvent(new DragEvent('dragover', { dataTransfer: dt, bubbles: true, cancelable: true }));
      el.dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
    });
    await expect(inlineForm.getByRole('alert')).toContainText(/仅支持/);
    await expect(inlineForm.locator('img[alt="配图预览"]')).toHaveCount(0);

    // 2) 拖入伪造扩展名的非法 MIME 文件也应被拒绝
    await textarea.evaluate((el) => {
      const file = new File(['<script>alert(1)</script>'], 'fake.png', { type: 'text/html' });
      const dt = new DataTransfer();
      dt.items.add(file);
      el.dispatchEvent(new DragEvent('dragover', { dataTransfer: dt, bubbles: true, cancelable: true }));
      el.dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
    });
    await expect(inlineForm.getByRole('alert')).toContainText(/仅支持/);
    await expect(inlineForm.locator('img[alt="配图预览"]')).toHaveCount(0);

    // 3) 拖入合法 PNG 图片应清除报错并展示预览，提交后自动上传并持久化
    await textarea.evaluate((el, base64Png) => {
      const bin = atob(base64Png);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
      const file = new File([bytes], 'folder-drop.png', { type: 'image/png' });
      const dt = new DataTransfer();
      dt.items.add(file);
      el.dispatchEvent(new DragEvent('dragenter', { dataTransfer: dt, bubbles: true, cancelable: true }));
      el.dispatchEvent(new DragEvent('dragover', { dataTransfer: dt, bubbles: true, cancelable: true }));
      el.dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
    }, TINY_PNG.toString('base64'));

    await expect(inlineForm.locator('img[alt="配图预览"]').first()).toBeVisible({ timeout: 8000 });
    await expect(inlineForm.getByRole('alert')).toHaveCount(0);

    const postText = `直接拖拽图片上传验证-${Date.now()} #DragDrop`;
    await textarea.fill(postText);

    const uploadPromise = page.waitForResponse(
      (res) => res.url().includes('/api/uploads') && res.request().method() === 'POST'
    );
    const postPromise = page.waitForResponse(
      (res) => res.url().endsWith('/api/posts') && res.request().method() === 'POST'
    );
    await inlineForm.locator('button[type="submit"]').click();

    const uploadRes = await uploadPromise;
    expect(uploadRes.status()).toBe(201);
    const postRes = await postPromise;
    expect(postRes.status()).toBe(201);
    const createdPost = (await postRes.json()).post;
    expect(createdPost.imageUrl).toMatch(/^\/api\/uploads\//);

    await page.reload();
    const publishedCard = page.locator('article').filter({ hasText: postText }).first();
    await expect(publishedCard).toBeVisible({ timeout: 10000 });
    await expect(publishedCard.locator(`img[src="${createdPost.imageUrl}"]`).first()).toBeVisible();

    expect(pageErrors, '拖拽上传流程不应产生前端异常').toEqual([]);
  });

  test('AC-3: 正文粘贴包含 URL 文本自动识别与格式化，纯文本粘贴不受干扰且发布后链接可点击', async ({
    page,
  }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    await loginUser(page.request, makeEmail('paste-url'), '外链识别测试');
    await page.goto('/');

    const inlineForm = page.locator('main form[data-testid="post-composer-form"]').first();
    const textarea = inlineForm.locator('textarea').first();
    await expect(textarea).toBeVisible({ timeout: 10000 });

    // 1) 普通纯文本粘贴不被异常截获（preventDefault 应为 false）
    const plainPastePrevented = await textarea.evaluate((el) => {
      const dt = new DataTransfer();
      dt.setData('text/plain', '这是一段不包含链接的纯文本');
      const evt = new ClipboardEvent('paste', {
        clipboardData: dt,
        bubbles: true,
        cancelable: true,
      });
      el.dispatchEvent(evt);
      return evt.defaultPrevented;
    });
    expect(plainPastePrevented, '纯文本粘贴不应被拦截').toBe(false);
    await expect(inlineForm.getByTestId('composer-detected-links')).toHaveCount(0);

    // 2) 粘贴包含紧贴中文字符的外链文本 -> 自动识别并格式化空格 + 展示外链预览标签
    const targetUrl = `https://developers.cloudflare.com/d1/?ref=${Date.now().toString().slice(-4)}`;
    await textarea.click();
    await textarea.evaluate((el, url) => {
      const dt = new DataTransfer();
      dt.setData('text/plain', `推荐阅读${url}非常实用`);
      const evt = new ClipboardEvent('paste', {
        clipboardData: dt,
        bubbles: true,
        cancelable: true,
      });
      el.dispatchEvent(evt);
    }, targetUrl);

    await expect(textarea).toHaveValue(`推荐阅读 ${targetUrl} 非常实用`);
    const detectedBox = inlineForm.getByTestId('composer-detected-links');
    await expect(detectedBox).toBeVisible({ timeout: 8000 });
    const detectedAnchor = detectedBox.locator(`a[href="${targetUrl}"]`);
    await expect(detectedAnchor).toBeVisible();
    await expect(detectedAnchor).toContainText('developers.cloudflare.com');

    // 3) 连续粘贴第二个链接不会出现死循环或重复崩溃，且两个链接都被识别
    const secondUrl = 'https://github.com/cloudflare/workers-sdk';
    await textarea.evaluate((el, url) => {
      const dt = new DataTransfer();
      dt.setData('text/plain', `以及源码仓库 ${url}！`);
      const evt = new ClipboardEvent('paste', {
        clipboardData: dt,
        bubbles: true,
        cancelable: true,
      });
      el.dispatchEvent(evt);
    }, secondUrl);

    await expect(detectedBox.locator(`a[href="${secondUrl}"]`)).toBeVisible();

    // 4) 发布该动态并确认发布后的动态卡片中自动渲染为可点击外链
    const createPromise = page.waitForResponse(
      (res) => res.url().endsWith('/api/posts') && res.request().method() === 'POST'
    );
    await inlineForm.locator('button[type="submit"]').click();
    const createRes = await createPromise;
    expect(createRes.status()).toBe(201);

    const card = page.locator('article').filter({ hasText: targetUrl }).first();
    await expect(card).toBeVisible({ timeout: 10000 });
    const cardLink = card.locator(`a[href="${targetUrl}"]`).first();
    await expect(cardLink).toBeVisible();
    await expect(cardLink).toHaveAttribute('target', '_blank');
    await expect(cardLink).toHaveAttribute('rel', /noopener/);

    expect(pageErrors, '粘贴外链识别流程不应产生前端异常').toEqual([]);
  });

  test('AC-4: 手机端 (375px) 与平板端 (768px) 发布界面响应式布局无溢出', async ({ page }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));

    await loginUser(page.request, makeEmail('responsive-ui'), '移动端体验官');

    for (const viewport of [
      { width: 375, height: 812 },
      { width: 768, height: 1024 },
    ]) {
      await page.setViewportSize(viewport);
      await page.goto('/');

      const inlineForm = page.locator('main form[data-testid="post-composer-form"]').first();
      await expect(inlineForm).toBeVisible({ timeout: 10000 });
      await expect(inlineForm.locator('input[type="file"]')).toHaveCount(0);
      await expect(inlineForm.locator('input[type="url"]')).toHaveCount(0);

      // 粘贴超长外链检查移动端不会导致横向溢出
      const longUrl = `https://developers.cloudflare.com/workers/runtime-apis/durable-objects/very-long-segment-for-mobile-overflow-check-${viewport.width}`;
      const textarea = inlineForm.locator('textarea').first();
      await textarea.click();
      await textarea.evaluate((el, url) => {
        const dt = new DataTransfer();
        dt.setData('text/plain', `移动端测试 ${url}`);
        el.dispatchEvent(
          new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true })
        );
      }, longUrl);

      await expect(inlineForm.getByTestId('composer-detected-links')).toBeVisible();

      const overflowCheck = await page.evaluate(() => {
        const docOverflow = document.documentElement.scrollWidth - window.innerWidth;
        const form = document.querySelector('main form[data-testid="post-composer-form"]');
        const formRect = form?.getBoundingClientRect();
        const submitBtn = form?.querySelector('button[type="submit"]')?.getBoundingClientRect();
        return {
          docOverflow,
          formFits: formRect ? formRect.right <= window.innerWidth + 1 : false,
          submitFits: submitBtn ? submitBtn.right <= window.innerWidth + 1 : false,
        };
      });
      expect(
        overflowCheck.docOverflow,
        `${viewport.width}px 视口下页面不应发生横向溢出`
      ).toBeLessThanOrEqual(2);
      expect(overflowCheck.formFits, `${viewport.width}px 下内联发布框应完整落在视口内`).toBe(
        true
      );
      expect(overflowCheck.submitFits, `${viewport.width}px 下发布按钮应完整可见`).toBe(true);

      // 检查弹窗发布框在当前分辨率下也能正常打开且不横向溢出
      const openDialogBtn = page.getByRole('button', { name: /发布动态/ }).first();
      await openDialogBtn.click();
      const dialog = page.getByRole('dialog').first();
      await expect(dialog).toBeVisible({ timeout: 10000 });
      const dialogBox = await dialog.boundingBox();
      expect(dialogBox).not.toBeNull();
      if (dialogBox) {
        expect(dialogBox.x).toBeGreaterThanOrEqual(0);
        expect(dialogBox.x + dialogBox.width).toBeLessThanOrEqual(viewport.width + 2);
      }
      await dialog.getByRole('button', { name: /取消/ }).click();
      await expect(dialog).toHaveCount(0);
    }

    expect(pageErrors, '响应式布局检查不应产生前端异常').toEqual([]);
  });
});
